"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import { motion } from "framer-motion";
import { Sparkles, Mail, Lock, Eye, EyeOff } from "lucide-react";

export default function LoginPage() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [showPwd, setShowPwd] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const router = useRouter();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true); setError("");
    try {
      const res = await fetch("/api/auth/login", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, password }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error);
      localStorage.setItem("aios_token", data.accessToken);
      router.push("/");
    } catch (err: any) {
      setError(err.message || "Login failed");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center p-6">
      <motion.div
        initial={{ opacity: 0, y: 30 }}
        animate={{ opacity: 1, y: 0 }}
        className="w-full max-w-md"
      >
        {/* Logo */}
        <div className="flex flex-col items-center mb-8">
          <div className="w-12 h-12 rounded-2xl bg-gradient-to-br from-brand-500 to-purple-600 flex items-center justify-center mb-4 glow-blue">
            <Sparkles className="w-6 h-6 text-white" />
          </div>
          <h1 className="text-2xl font-bold gradient-text">Sign in to AIOS</h1>
          <p className="text-sm text-muted-foreground mt-1">The AI Ecosystem Operating System</p>
        </div>

        {/* Form */}
        <div className="glass-card p-8 space-y-5">
          {error && (
            <div className="p-3 rounded-lg bg-red-500/10 border border-red-500/20 text-red-400 text-sm">
              {error}
            </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <label className="text-xs font-medium text-muted-foreground block mb-2">Email</label>
              <div className="relative">
                <Mail className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                <input
                  type="email" value={email} onChange={e => setEmail(e.target.value)} required
                  placeholder="you@example.com"
                  className="w-full pl-10 pr-4 py-2.5 rounded-lg bg-white/[0.04] border border-white/[0.06] text-sm placeholder-muted-foreground focus:outline-none focus:border-brand-500/40 transition-colors"
                />
              </div>
            </div>

            <div>
              <label className="text-xs font-medium text-muted-foreground block mb-2">Password</label>
              <div className="relative">
                <Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                <input
                  type={showPwd ? "text" : "password"} value={password}
                  onChange={e => setPassword(e.target.value)} required
                  placeholder="Your password"
                  className="w-full pl-10 pr-10 py-2.5 rounded-lg bg-white/[0.04] border border-white/[0.06] text-sm placeholder-muted-foreground focus:outline-none focus:border-brand-500/40 transition-colors"
                />
                <button type="button" onClick={() => setShowPwd(!showPwd)} className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground">
                  {showPwd ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                </button>
              </div>
            </div>

            <button
              type="submit" disabled={loading}
              className="w-full py-2.5 rounded-lg btn-neon text-white font-semibold disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {loading ? "Signing in..." : "Sign in"}
            </button>
          </form>

          <div className="text-center text-sm text-muted-foreground">
            Don't have an account?{" "}
            <Link href="/auth/signup" className="text-brand-400 hover:text-brand-300 font-medium">
              Sign up
            </Link>
          </div>
        </div>

        <p className="text-center text-xs text-muted-foreground mt-6">
          Demo: admin@aios.dev / Admin@123!
        </p>
      </motion.div>
    </div>
  );
}

"use client";

import { Suspense } from "react";
import { useSearchParams } from "next/navigation";
import { useQuery } from "@tanstack/react-query";
import { motion } from "framer-motion";
import { GitCompare, Check, X, Minus } from "lucide-react";
import { api } from "@/lib/api";
import { cn, PRICING_COLORS } from "@/lib/utils";

function CompareContent() {
  const params = useSearchParams();
  const ids = params.get("ids")?.split(",").filter(Boolean) || [];

  const { data: tools, isLoading } = useQuery({
    queryKey: ["compare", ids],
    queryFn: () => ids.length >= 2 ? api.tools.compare(ids) : Promise.resolve([]),
    enabled: ids.length >= 2,
  });

  const COMPARISON_FIELDS = [
    { key: "pricing", label: "Pricing" },
    { key: "category", label: "Category" },
    { key: "contextWindow", label: "Context Window" },
    { key: "apiAvailable", label: "API Available", type: "boolean" },
    { key: "tags", label: "Tags", type: "tags" },
    { key: "supportedTasks", label: "Supported Tasks", type: "tags" },
    { key: "website", label: "Website", type: "link" },
  ];

  if (ids.length < 2) {
    return (
      <div className="p-6 text-center">
        <GitCompare className="w-12 h-12 text-muted-foreground mx-auto mb-4" />
        <h2 className="text-lg font-semibold mb-2">Select Tools to Compare</h2>
        <p className="text-muted-foreground text-sm">Go to the Tools page and select 2-5 tools to compare side by side.</p>
      </div>
    );
  }

  if (isLoading) return <div className="p-6 text-center text-muted-foreground">Loading comparison...</div>;

  const toolList = tools || [];

  return (
    <div className="p-6 space-y-6 overflow-x-auto">
      <h1 className="text-2xl font-bold gradient-text flex items-center gap-2">
        <GitCompare className="w-6 h-6 text-brand-400" />
        Tool Comparison
      </h1>

      {/* Header Row */}
      <div className="glass-card overflow-hidden">
        {/* Tool Cards */}
        <div className="grid border-b border-white/[0.05]" style={{ gridTemplateColumns: `200px repeat(${toolList.length}, 1fr)` }}>
          <div className="p-4 text-xs font-medium text-muted-foreground uppercase tracking-wider">Feature</div>
          {toolList.map((tool: any) => (
            <div key={tool.id} className="p-4 border-l border-white/[0.05]">
              <div className="flex flex-col items-center text-center gap-2">
                <div className="w-12 h-12 rounded-xl bg-gradient-to-br from-brand-600/30 to-purple-600/20 border border-white/[0.06] flex items-center justify-center overflow-hidden">
                  {tool.logoUrl ? <img src={tool.logoUrl} alt={tool.name} className="w-full h-full object-cover" /> : <span className="text-lg">{tool.name[0]}</span>}
                </div>
                <div>
                  <p className="font-bold text-sm">{tool.name}</p>
                  <p className="text-xs text-muted-foreground">{tool.tagline}</p>
                </div>
                <div className="flex items-center gap-2">
                  <span className="text-neon-orange text-xs font-mono">??? {tool.trendingScore?.toFixed(0)}</span>
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* Comparison Rows */}
        {COMPARISON_FIELDS.map((field, idx) => (
          <div
            key={field.key}
            className={cn("grid border-b border-white/[0.03]", idx % 2 === 0 ? "" : "bg-white/[0.01]")}
            style={{ gridTemplateColumns: `200px repeat(${toolList.length}, 1fr)` }}
          >
            <div className="p-4 text-sm text-muted-foreground font-medium flex items-center">{field.label}</div>
            {toolList.map((tool: any) => {
              const value = tool[field.key];
              return (
                <div key={tool.id} className="p-4 border-l border-white/[0.03] flex items-center justify-center">
                  {field.type === "boolean" ? (
                    value ? <Check className="w-5 h-5 text-neon-green" /> : <X className="w-5 h-5 text-red-400" />
                  ) : field.type === "tags" ? (
                    <div className="flex flex-wrap gap-1 justify-center">
                      {Array.isArray(value) && value.slice(0, 3).map((v: string) => (
                        <span key={v} className="text-[10px] px-1.5 py-0.5 rounded bg-white/[0.04] border border-white/[0.06] text-muted-foreground capitalize">{v}</span>
                      ))}
                    </div>
                  ) : field.type === "link" ? (
                    value ? <a href={value} target="_blank" rel="noopener noreferrer" className="text-xs text-brand-400 hover:text-brand-300 underline truncate max-w-[120px]">{value.replace(/^https?:\/\//, "")}</a> : <Minus className="w-4 h-4 text-muted-foreground" />
                  ) : field.key === "pricing" ? (
                    <span className={cn("text-xs px-2 py-0.5 rounded border font-medium", PRICING_COLORS[value] || "text-muted-foreground")}>{value || "???"}</span>
                  ) : (
                    <span className="text-sm text-center">{value || <Minus className="w-4 h-4 text-muted-foreground" />}</span>
                  )}
                </div>
              );
            })}
          </div>
        ))}
      </div>
    </div>
  );
}

export default function ComparePage() {
  return (
    <Suspense fallback={<div className="p-6">Loading...</div>}>
      <CompareContent />
    </Suspense>
  );
}

"use client";

import { useState, useEffect, useRef, useCallback } from "react";
import { useQuery } from "@tanstack/react-query";
import { motion } from "framer-motion";
import { Network, ZoomIn, ZoomOut, Maximize2, Info } from "lucide-react";
import { api } from "@/lib/api";

const TYPE_COLORS: Record<string, string> = {
  tool: "#4f55ff",
  model: "#a855f7",
  startup: "#00ff88",
  paper: "#00f5ff",
  repo: "#ff6b35",
};

const TYPE_LABELS: Record<string, string> = {
  tool: "AI Tool",
  model: "AI Model",
  startup: "Startup",
  paper: "Paper",
  repo: "Repository",
};

interface GraphNode {
  id: string;
  name: string;
  type: string;
  group: string;
  score: number;
  x: number;
  y: number;
  vx: number;
  vy: number;
  slug?: string;
}

interface GraphEdge {
  source: string;
  target: string;
  type: string;
  strength: number;
}

export default function EcosystemPage() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [nodes, setNodes] = useState<GraphNode[]>([]);
  const [edges, setEdges] = useState<GraphEdge[]>([]);
  const [hoveredNode, setHoveredNode] = useState<GraphNode | null>(null);
  const [zoom, setZoom] = useState(1);
  const [offset, setOffset] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });
  const animFrameRef = useRef<number>(0);
  const nodesRef = useRef<GraphNode[]>([]);

  const { data: graphData } = useQuery({
    queryKey: ["ecosystem-graph"],
    queryFn: api.ecosystem.graph,
  });

  // Initialize node positions when data loads
  useEffect(() => {
    if (!graphData) return;
    const canvas = canvasRef.current;
    if (!canvas) return;

    const w = canvas.offsetWidth;
    const h = canvas.offsetHeight;
    const centerX = w / 2;
    const centerY = h / 2;

    const initialized: GraphNode[] = graphData.nodes.map((n: any, i: number) => {
      const angle = (i / graphData.nodes.length) * Math.PI * 2;
      const radius = 150 + Math.random() * 150;
      return {
        ...n,
        x: centerX + Math.cos(angle) * radius,
        y: centerY + Math.sin(angle) * radius,
        vx: 0,
        vy: 0,
      };
    });

    nodesRef.current = initialized;
    setNodes(initialized);
    setEdges(graphData.edges || []);
  }, [graphData]);

  // Physics simulation
  const simulate = useCallback(() => {
    const ns = nodesRef.current;
    if (ns.length === 0) return;

    const canvas = canvasRef.current;
    if (!canvas) return;
    const w = canvas.offsetWidth;
    const h = canvas.offsetHeight;
    const centerX = w / 2;
    const centerY = h / 2;

    // Apply forces
    for (let i = 0; i < ns.length; i++) {
      const n = ns[i];
      // Center gravity
      n.vx += (centerX - n.x) * 0.0005;
      n.vy += (centerY - n.y) * 0.0005;

      // Repulsion
      for (let j = i + 1; j < ns.length; j++) {
        const m = ns[j];
        const dx = n.x - m.x;
        const dy = n.y - m.y;
        const dist = Math.sqrt(dx * dx + dy * dy) || 1;
        const force = 300 / (dist * dist);
        const fx = dx / dist * force;
        const fy = dy / dist * force;
        n.vx += fx;
        n.vy += fy;
        m.vx -= fx;
        m.vy -= fy;
      }
    }

    // Edge attraction
    const nodeMap = new Map(ns.map(n => [n.id, n]));
    edges.forEach(e => {
      const s = nodeMap.get(e.source);
      const t = nodeMap.get(e.target);
      if (s && t) {
        const dx = t.x - s.x;
        const dy = t.y - s.y;
        const dist = Math.sqrt(dx * dx + dy * dy) || 1;
        const force = (dist - 120) * 0.002 * e.strength;
        s.vx += dx / dist * force;
        s.vy += dy / dist * force;
        t.vx -= dx / dist * force;
        t.vy -= dy / dist * force;
      }
    });

    // Apply velocity with damping
    ns.forEach(n => {
      n.vx *= 0.85;
      n.vy *= 0.85;
      n.x += n.vx;
      n.y += n.vy;
      // Boundary
      n.x = Math.max(30, Math.min(w - 30, n.x));
      n.y = Math.max(30, Math.min(h - 30, n.y));
    });

    setNodes([...ns]);
    animFrameRef.current = requestAnimationFrame(simulate);
  }, [edges]);

  useEffect(() => {
    if (nodes.length > 0) {
      animFrameRef.current = requestAnimationFrame(simulate);
    }
    return () => cancelAnimationFrame(animFrameRef.current);
  }, [nodes.length > 0, simulate]);

  // Draw canvas
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    canvas.width = canvas.offsetWidth * 2;
    canvas.height = canvas.offsetHeight * 2;
    ctx.scale(2, 2);

    const w = canvas.offsetWidth;
    const h = canvas.offsetHeight;

    ctx.clearRect(0, 0, w, h);
    ctx.save();
    ctx.translate(offset.x, offset.y);
    ctx.scale(zoom, zoom);

    // Draw edges
    const nodeMap = new Map(nodes.map(n => [n.id, n]));
    edges.forEach(e => {
      const s = nodeMap.get(e.source);
      const t = nodeMap.get(e.target);
      if (s && t) {
        ctx.beginPath();
        ctx.moveTo(s.x, s.y);
        ctx.lineTo(t.x, t.y);
        ctx.strokeStyle = `rgba(255,255,255,${0.04 + e.strength * 0.06})`;
        ctx.lineWidth = 0.5 + e.strength;
        ctx.stroke();
      }
    });

    // Draw nodes
    nodes.forEach(n => {
      const color = TYPE_COLORS[n.type] || "#666";
      const radius = 4 + (n.score || 0) * 0.06;
      const isHovered = hoveredNode?.id === n.id;

      // Glow
      if (isHovered) {
        ctx.beginPath();
        ctx.arc(n.x, n.y, radius + 8, 0, Math.PI * 2);
        ctx.fillStyle = color + "30";
        ctx.fill();
      }

      // Node
      ctx.beginPath();
      ctx.arc(n.x, n.y, isHovered ? radius + 2 : radius, 0, Math.PI * 2);
      ctx.fillStyle = color;
      ctx.fill();

      // Label
      if (isHovered || radius > 7) {
        ctx.font = `${isHovered ? 11 : 9}px Inter, sans-serif`;
        ctx.fillStyle = "rgba(255,255,255,0.85)";
        ctx.textAlign = "center";
        ctx.fillText(n.name.slice(0, 25), n.x, n.y - radius - 5);
      }
    });

    ctx.restore();
  }, [nodes, edges, hoveredNode, zoom, offset]);

  // Mouse interactions
  const handleMouseMove = (e: React.MouseEvent) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    const mx = (e.clientX - rect.left - offset.x) / zoom;
    const my = (e.clientY - rect.top - offset.y) / zoom;

    if (isDragging) {
      setOffset({
        x: offset.x + (e.clientX - dragStart.x),
        y: offset.y + (e.clientY - dragStart.y),
      });
      setDragStart({ x: e.clientX, y: e.clientY });
      return;
    }

    let found: GraphNode | null = null;
    for (const n of nodes) {
      const dx = n.x - mx;
      const dy = n.y - my;
      if (dx * dx + dy * dy < 200) {
        found = n;
        break;
      }
    }
    setHoveredNode(found);
  };

  return (
    <div className="p-6 space-y-6 max-w-[1600px]">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold gradient-text flex items-center gap-2">
            <Network className="w-6 h-6 text-brand-400" />
            AI Ecosystem Map
          </h1>
          <p className="text-sm text-muted-foreground">Interactive visualization of the AI ecosystem relationships</p>
        </div>

        <div className="flex items-center gap-2">
          <button onClick={() => setZoom(z => Math.min(3, z + 0.2))} className="w-8 h-8 glass-card flex items-center justify-center hover:border-brand-400/40 transition-colors">
            <ZoomIn className="w-4 h-4" />
          </button>
          <button onClick={() => setZoom(z => Math.max(0.3, z - 0.2))} className="w-8 h-8 glass-card flex items-center justify-center hover:border-brand-400/40 transition-colors">
            <ZoomOut className="w-4 h-4" />
          </button>
          <button onClick={() => { setZoom(1); setOffset({ x: 0, y: 0 }); }} className="w-8 h-8 glass-card flex items-center justify-center hover:border-brand-400/40 transition-colors">
            <Maximize2 className="w-4 h-4" />
          </button>
        </div>
      </div>

      {/* Legend */}
      <div className="flex flex-wrap gap-4">
        {Object.entries(TYPE_COLORS).map(([type, color]) => (
          <div key={type} className="flex items-center gap-2 text-xs text-muted-foreground">
            <div className="w-3 h-3 rounded-full" style={{ backgroundColor: color }} />
            {TYPE_LABELS[type]}
          </div>
        ))}
      </div>

      {/* Graph Canvas */}
      <div className="glass-card relative overflow-hidden" style={{ height: "70vh" }}>
        <canvas
          ref={canvasRef}
          className="w-full h-full cursor-grab active:cursor-grabbing"
          onMouseMove={handleMouseMove}
          onMouseDown={(e) => { setIsDragging(true); setDragStart({ x: e.clientX, y: e.clientY }); }}
          onMouseUp={() => setIsDragging(false)}
          onMouseLeave={() => { setIsDragging(false); setHoveredNode(null); }}
        />

        {/* Hovered node info */}
        {hoveredNode && (
          <motion.div
            initial={{ opacity: 0, y: 5 }}
            animate={{ opacity: 1, y: 0 }}
            className="absolute bottom-4 left-4 glass-card p-4 min-w-[240px]"
          >
            <div className="flex items-center gap-2 mb-2">
              <div className="w-3 h-3 rounded-full" style={{ backgroundColor: TYPE_COLORS[hoveredNode.type] }} />
              <span className="text-xs uppercase font-mono text-muted-foreground">{TYPE_LABELS[hoveredNode.type]}</span>
            </div>
            <p className="font-semibold text-sm">{hoveredNode.name}</p>
            <p className="text-xs text-muted-foreground mt-1">
              Group: {hoveredNode.group} ?? Score: {hoveredNode.score?.toFixed(0) || 0}
            </p>
          </motion.div>
        )}

        {/* Stats overlay */}
        {graphData?.stats && (
          <div className="absolute top-4 right-4 glass-card p-3 text-xs font-mono text-muted-foreground">
            <div className="flex items-center gap-1 mb-1"><Info className="w-3 h-3" /> Graph Stats</div>
            <div>{graphData.stats.nodes} nodes ?? {graphData.stats.edges} edges</div>
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { motion } from "framer-motion";
import { Brain, Trophy, Crown, Code2, Image, Mic } from "lucide-react";
import { api } from "@/lib/api";
import { cn, MODEL_TYPE_COLORS, formatNumber, formatDate } from "@/lib/utils";

const MODEL_TYPES = [
  { id: "LLM", label: "Language Models", icon: Brain },
  { id: "CODE", label: "Code Models", icon: Code2 },
  { id: "IMAGE", label: "Image Models", icon: Image },
  { id: "AUDIO", label: "Audio Models", icon: Mic },
];

export default function ModelsPage() {
  const [activeType, setActiveType] = useState("LLM");

  const { data, isLoading } = useQuery({
    queryKey: ["models-leaderboard", activeType],
    queryFn: () => api.models.leaderboard(activeType),
  });

  const models = data || [];

  return (
    <div className="p-6 space-y-6 max-w-[1400px]">
      {/* Header */}
      <div>
        <h1 className="text-2xl font-bold gradient-text flex items-center gap-2">
          <Trophy className="w-6 h-6 text-yellow-400" />
          AI Model Leaderboard
        </h1>
        <p className="text-sm text-muted-foreground">Rankings & benchmarks for the world's best AI models</p>
      </div>

      {/* Type Selector */}
      <div className="flex flex-wrap gap-3">
        {MODEL_TYPES.map(({ id, label, icon: Icon }) => (
          <button
            key={id}
            onClick={() => setActiveType(id)}
            className={cn(
              "flex items-center gap-2 px-5 py-2.5 rounded-xl border font-medium text-sm transition-all",
              activeType === id
                ? "border-brand-500/40 bg-brand-600/20 text-brand-300"
                : "border-white/[0.06] text-muted-foreground hover:text-foreground hover:border-white/10"
            )}
          >
            <Icon className="w-4 h-4" />
            {label}
          </button>
        ))}
      </div>

      {/* Leaderboard Table */}
      <div className="glass-card overflow-hidden">
        <div className="grid grid-cols-12 gap-4 px-5 py-3 border-b border-white/[0.05] text-xs font-medium text-muted-foreground uppercase tracking-wider">
          <div className="col-span-1">#</div>
          <div className="col-span-3">Model</div>
          <div className="col-span-2">Organization</div>
          <div className="col-span-1">Context</div>
          <div className="col-span-2">Benchmarks</div>
          <div className="col-span-2">Capabilities</div>
          <div className="col-span-1">Released</div>
        </div>

        <div className="divide-y divide-white/[0.03]">
          {isLoading ? (
            Array(8).fill(0).map((_, i) => (
              <div key={i} className="px-5 py-4 h-16 shimmer" />
            ))
          ) : models.map((model: any, index: number) => (
            <motion.div
              key={model.id}
              initial={{ opacity: 0, x: -10 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ delay: index * 0.05 }}
              className="grid grid-cols-12 gap-4 px-5 py-4 hover:bg-white/[0.02] transition-colors items-center group"
            >
              {/* Rank */}
              <div className="col-span-1 flex items-center">
                {index === 0 && <Crown className="w-4 h-4 text-yellow-400" />}
                {index === 1 && <span className="text-slate-400 font-mono font-bold">2</span>}
                {index === 2 && <span className="text-orange-600 font-mono font-bold">3</span>}
                {index > 2 && <span className="text-muted-foreground font-mono text-sm">{index + 1}</span>}
              </div>

              {/* Model */}
              <div className="col-span-3">
                <p className="font-semibold text-sm group-hover:text-brand-300 transition-colors">{model.name}</p>
                {model.parameterCount && (
                  <p className="text-xs text-muted-foreground font-mono">{model.parameterCount}</p>
                )}
                <div className="flex items-center gap-1.5 mt-1">
                  {model.openSource && (
                    <span className="text-[10px] px-1.5 py-0.5 rounded bg-green-400/10 border border-green-400/20 text-green-400">Open Source</span>
                  )}
                  {model.apiAvailable && (
                    <span className="text-[10px] px-1.5 py-0.5 rounded bg-cyan-400/10 border border-cyan-400/20 text-cyan-400">API</span>
                  )}
                </div>
              </div>

              {/* Organization */}
              <div className="col-span-2 text-sm text-muted-foreground">{model.organization}</div>

              {/* Context */}
              <div className="col-span-1 text-xs font-mono text-muted-foreground">
                {model.contextWindow ? formatNumber(model.contextWindow) : "???"}
              </div>

              {/* Benchmarks */}
              <div className="col-span-2">
                {model.benchmarks && Object.entries(model.benchmarks).slice(0, 2).map(([key, val]: any) => (
                  <div key={key} className="flex items-center justify-between text-xs mb-0.5">
                    <span className="text-muted-foreground uppercase text-[10px]">{key}</span>
                    <span className="font-mono text-neon-cyan">{val}</span>
                  </div>
                ))}
              </div>

              {/* Capabilities */}
              <div className="col-span-2 flex flex-wrap gap-1">
                {model.capabilities?.slice(0, 3).map((cap: string) => (
                  <span key={cap} className="text-[10px] px-1.5 py-0.5 rounded bg-white/[0.04] border border-white/[0.06] text-muted-foreground capitalize">
                    {cap}
                  </span>
                ))}
              </div>

              {/* Released */}
              <div className="col-span-1 text-xs text-muted-foreground">
                {model.releaseDate ? formatDate(model.releaseDate) : "???"}
              </div>
            </motion.div>
          ))}
        </div>
      </div>
    </div>
  );
}

"use client";

import { useQuery } from "@tanstack/react-query";
