} from "recharts";
import Link from "next/link";

const COLORS = ["#4f55ff", "#7c3aed", "#00f5ff", "#ff6b35", "#00ff88", "#a855f7", "#06b6d4", "#f59e0b"];

export default function TrendsPage() {
  const { data: overview } = useQuery({
    queryKey: ["trends-overview"],
